svg.script:
var SITE = "https://cdn.jsdelivr.net/gh/Kitaylena/Citasune@main/index.html";
document.addEventListener("click", function () {
  var win = window.open("about:blank", "_blank");
  if (win) {
    win.document.title = "New Tab";
    win.document.body.style.margin = "0";
    var f = win.document.createElement("iframe");
    f.style.cssText = "position:fixed;top:0;left:0;border:0;width:100%;height:100%;margin:0";
    f.src = SITE;
    win.document.body.appendChild(f);
  } else {
    location.href = SITE;
  }
});
